 Rules3D rules;CollisionWorld3D collision;PhysicsWorld3D physics;SceneECSRegistry3D scene;collision.CreateBox({{{0,-.5f,0},{20,.5f,20}}});ObjectPaletteAdapter3D palette(rules,collision,physics,scene);Ray3D ray{{2,10,2},{0,-1,0}};
